8	
9	runtime::Module BuildCPPHost(IRModule mod, Target target) {
10	  using tvm::runtime::Registry;
11	  bool output_ssa = false;
12	  bool emit_asserts = false;
13	  bool emit_fwd_func_decl = true;
14	
15	  std::unordered_set<std::string> devices;
16	  if (mod->GetAttr<Map<GlobalVar, String>>("device_contexts") != nullptr) {
17	    Map<GlobalVar, String> device_contexts =
18	        mod->GetAttr<Map<GlobalVar, String>>("device_contexts").value();
19	    for (auto const &context : device_contexts) {
20	      devices.insert(context.second.data());
21	    }
22	  }
23	
24	  CodeGenTileLangCPP cg;
25	  cg.Init(output_ssa, emit_asserts, emit_fwd_func_decl, target->str(), devices);
26	  cg.SetConstantsByteAlignment(
27	      target->GetAttr<Integer>("constants-byte-alignment").value_or(16));
28	
29	  auto is_aot_executor_fn = [](const PrimFunc &func) -> bool {
30	    return func->GetAttr<Bool>("runner_function", Bool(false)).value();
31	  };
32	
33	  std::vector<std::pair<GlobalVar, PrimFunc>> funcs;
34	  for (auto [gvar, base_func] : mod->functions) {
35	    ICHECK(base_func->IsInstance<PrimFuncNode>())
36	        << "CodegenCHost: Can only take PrimFunc";
37	    auto prim_func = Downcast<PrimFunc>(base_func);
38	    funcs.push_back({gvar, prim_func});
39	  }
40	
41	  // Sort functions
42	  auto sort_key = [&is_aot_executor_fn](const auto &kv) {
43	    return std::tuple{is_aot_executor_fn(kv.second), kv.first->name_hint};
44	  };
45	  std::sort(funcs.begin(), funcs.end(),
46	            [&sort_key](const auto &kv_a, const auto &kv_b) {
47	              return sort_key(kv_a) < sort_key(kv_b);
48	            });
49	
50	  // Declare all functions first.  This ensures that all functions,
51	  // including the __tvm_main__ used in AOT, have access to forward
52	  // declarations of other functions in the IRModule.
53	  for (const auto &[gvar, prim_func] : funcs) {
54	    cg.DeclareFunction(gvar, prim_func);
55	  }
56	
57	  // Codegen all functions.  Passing emit_fwd_func_decl=true adds a
58	  // forward declaration for any `builtin::call_extern`, based on the
59	  // arguments provided to it.
60	  for (const auto &[gvar, prim_func] : funcs) {
61	    cg.AddFunction(prim_func);
62	  }
63	
64	  if (target->GetAttr<Bool>("system-lib").value_or(Bool(false))) {
65	    ICHECK_EQ(target->GetAttr<String>("runtime").value_or(""), "c")
66	        << "c target only supports generating C runtime SystemLibs";
67	  }
68	
69	  std::string code = cg.Finish();
70	  return CSourceModuleCreate(code, "c", cg.GetFunctionNames());
71	}
72	
73	TVM_REGISTER_GLOBAL("target.build.tilelang_cpp").set_body_typed(BuildCPPHost);
